static const unsigned char gd_golden_sha[32] = { 0x46, 0x44, 0x71, 0x72, 0xdc, 0x9b, 0x2d, 0xa8, 0xda, 0xc8, 0x54, 0x5a, 0x56, 0x88, 0xab, 0x59, 0x1d, 0xad, 0x39, 0xe2, 0x9b, 0xe6, 0x33, 0x9c, 0x3d, 0x26, 0x49, 0x27, 0xd0, 0x94, 0xe9, 0x3e };
#define GD_GOLDEN_ROWS UINT64_C(17)
#define GD_GOLDEN_BYTES UINT64_C(4038)


static const cbm_store_graph_digest_limits_t gd_room = {UINT64_C(100000), UINT64_C(8388608)};
static int gd_sql(sqlite3 *db, const char *sql) {
    return sqlite3_exec(db, sql, NULL, NULL, NULL);
}
static bool gd_int(sqlite3 *db, const char *sql, int64_t want) {
    sqlite3_stmt *q=NULL;
    bool ok=sqlite3_prepare_v2(db,sql,-1,&q,NULL)==SQLITE_OK && sqlite3_step(q)==SQLITE_ROW &&
        sqlite3_column_int64(q,0)==want && sqlite3_step(q)==SQLITE_DONE;
    if (q && sqlite3_finalize(q)!=SQLITE_OK) ok=false;
    return ok;
}
static bool gd_seed(sqlite3 *db, bool reverse, bool meta) {
    static const char drop[] =
        "PRAGMA foreign_keys=OFF;"
        "DROP TABLE IF EXISTS edges;DROP TABLE IF EXISTS nodes;DROP TABLE IF EXISTS file_hashes;"
        "DROP TABLE IF EXISTS project_summaries;DROP TABLE IF EXISTS lsp_surface;"
        "DROP TABLE IF EXISTS index_unresolved_candidates;"
        "DROP TABLE IF EXISTS index_coverage;DROP TABLE IF EXISTS index_coverage_meta;"
        "DROP TABLE IF EXISTS projects;DROP TABLE IF EXISTS store_meta;";
    if (!db || gd_sql(db,drop)!=SQLITE_OK) return false;
    for (size_t i=0;i<8+(size_t)meta;i++) if (gd_sql(db,gd_schema[i])!=SQLITE_OK) return false;
    size_t n=sizeof(gd_inserts)/sizeof(gd_inserts[0]);
    for (size_t i=0;i<n;i++) if (gd_sql(db,gd_inserts[reverse?n-i-1:i])!=SQLITE_OK) return false;
    return !meta || gd_sql(db,"INSERT INTO store_meta VALUES('db_uid','0123456789abcdef'),"
        "('mutation_gen','7'),('future','opaque')")==SQLITE_OK;
}
static cbm_store_t *gd_fixture(bool reverse, bool meta) {
    cbm_store_t *s=cbm_store_open_memory();
    if (s && !gd_seed(cbm_store_get_db(s),reverse,meta)) { cbm_store_close(s);s=NULL; }
    return s;
}
static bool gd_zero(const cbm_store_graph_digest_t *v) {
    if (v->version || v->rows || v->framed_bytes) return false;
    for (size_t i=0;i<sizeof(v->sha256);i++) if (v->sha256[i]) return false;
    return true;
}
static bool gd_equal(const cbm_store_graph_digest_t *a,const cbm_store_graph_digest_t *b) {
    return a->version==b->version && a->rows==b->rows && a->framed_bytes==b->framed_bytes &&
        memcmp(a->sha256,b->sha256,sizeof(a->sha256))==0;
}
static bool gd_different(const cbm_store_graph_digest_t *a,const cbm_store_graph_digest_t *b) {
    return memcmp(a->sha256,b->sha256,sizeof(a->sha256))!=0;
}
static bool gd_read(cbm_store_t *s,const unsigned char *project,size_t len,
                    cbm_store_graph_digest_t *out) {
    cbm_store_read_scope_t *scope=NULL;
    int opened=s?cbm_store_read_scope_open(s,NULL,NULL,&scope):CBM_STORE_ERR;
    int rc=opened==CBM_STORE_OK?cbm_store_graph_digest(scope,project,len,&gd_room,out):CBM_STORE_GRAPH_DIGEST_ERROR;
    int closed=cbm_store_read_scope_close(scope);
    return opened==CBM_STORE_OK && rc==CBM_STORE_GRAPH_DIGEST_OK && closed==CBM_STORE_OK;
}
static bool gd_p(cbm_store_t *s,cbm_store_graph_digest_t *out) {
    return gd_read(s,(const unsigned char *)"p",1,out);
}
/* Caller closes the connection immediately after this failure helper. */
static bool gd_reject(cbm_store_t *s,cbm_store_graph_digest_status_t want) {
    cbm_store_read_scope_t *scope=NULL; cbm_store_graph_digest_t out;
    memset(&out,0xa5,sizeof(out));
    int opened=cbm_store_read_scope_open(s,NULL,NULL,&scope);
    int rc=opened==CBM_STORE_OK?cbm_store_graph_digest(scope,(const unsigned char *)"p",1,&gd_room,&out):-1;
    bool zero=gd_zero(&out);
    int latch=scope?cbm_store_read_scope_check(scope):0;
    int closed=cbm_store_read_scope_close(scope);
    return opened==CBM_STORE_OK && rc==(int)want && zero && latch==CBM_STORE_ERR && closed==CBM_STORE_ERR;
}
static int gd_stmt_count(sqlite3 *db) {
    int n=0;for(sqlite3_stmt *s=sqlite3_next_stmt(db,NULL);s;s=sqlite3_next_stmt(db,s))n++;
    return n;
}

typedef struct { uint64_t calls,trip; bool armed,stop; } gd_cancel_t;
/* Pure callback, including cancellation: only caller-owned scalar state. */
static bool gd_cancel(void *opaque) {
    gd_cancel_t *c=opaque;
    if (c->armed && c->calls<UINT64_MAX) c->calls++;
    return c->stop || (c->armed && c->trip && c->calls>=c->trip);
}

TEST(store_graph_digest_binds_unresolved_candidate_index) {
    cbm_store_t *s = cbm_store_open_memory();
    cbm_coverage_row_t row = {.rel_path = "calls.js",
                              .kind = "unresolved_calls",
                              .detail = "[{\"candidate\":\"p.target\"}]"};
    bool setup = s && cbm_store_upsert_project(s, "p", "/tmp/digest-candidates") == CBM_STORE_OK &&
                 cbm_store_upsert_file_hash(s, "p", "calls.js", "fixture", 0, 0) == CBM_STORE_OK &&
                 cbm_store_coverage_replace(s, "p", &row, 1) == CBM_STORE_OK;
    bool candidate_before = false, candidate_after = true;
    cbm_store_graph_digest_t before = {0}, after = {0};
    unsigned char content_before[CBM_STORE_GRAPH_DIGEST_BYTES] = {0},
                  content_after[CBM_STORE_GRAPH_DIGEST_BYTES] = {0};
    bool read_before =
        setup &&
        cbm_store_coverage_has_unresolved_candidate(s, "p", "p.target", &candidate_before) ==
            CBM_STORE_OK &&
        gd_p(s, &before) && cbm_store_graph_content_digest(s, "p", content_before) == CBM_STORE_OK;
    /* Deliberately bypass publication/generation advancement: inbound reads this table. */
    bool removed = read_before &&
                   gd_sql(cbm_store_get_db(s),
                          "DELETE FROM index_unresolved_candidates WHERE project='p'") == SQLITE_OK;
    bool read_after =
        removed &&
        cbm_store_coverage_has_unresolved_candidate(s, "p", "p.target", &candidate_after) ==
            CBM_STORE_OK &&
        gd_p(s, &after) && cbm_store_graph_content_digest(s, "p", content_after) == CBM_STORE_OK;
    cbm_store_close(s);
    ASSERT_TRUE(setup);
    ASSERT_TRUE(read_before);
    ASSERT_TRUE(candidate_before);
    ASSERT_TRUE(removed);
    ASSERT_TRUE(read_after);
    ASSERT_FALSE(candidate_after);
    ASSERT_TRUE(gd_different(&before, &after));
    ASSERT_TRUE(memcmp(content_before, content_after, sizeof(content_before)) != 0);
    PASS();
}

TEST(store_graph_digest_candidate_index_errors_are_not_legacy_absence) {
    cbm_store_t *s = gd_fixture(false, false);
    unsigned char legacy[CBM_STORE_GRAPH_DIGEST_BYTES] = {0},
                  again[CBM_STORE_GRAPH_DIGEST_BYTES] = {0};
    bool old = s && cbm_store_graph_content_digest(s, "p", legacy) == CBM_STORE_OK;
    bool malformed =
        old && gd_sql(cbm_store_get_db(s),
                      "CREATE TABLE index_unresolved_candidates(project TEXT,unexpected TEXT)") ==
                   SQLITE_OK;
    int content_rc = malformed ? cbm_store_graph_content_digest(s, "p", again) : CBM_STORE_OK;
    bool graph_rejected = malformed && gd_reject(s, CBM_STORE_GRAPH_DIGEST_SCHEMA);
    bool absent =
        graph_rejected &&
        gd_sql(cbm_store_get_db(s), "DROP TABLE index_unresolved_candidates") == SQLITE_OK &&
        cbm_store_graph_content_digest(s, "p", again) == CBM_STORE_OK;
    cbm_store_close(s);
    ASSERT_TRUE(old);
    ASSERT_TRUE(malformed);
    ASSERT_EQ(content_rc, CBM_STORE_ERR);
    ASSERT_TRUE(graph_rejected);
    ASSERT_TRUE(absent);
    ASSERT_TRUE(memcmp(legacy, again, sizeof(legacy)) == 0);
    PASS();
}

TEST(store_graph_digest_independent_canonical_golden) {
    cbm_store_t *s=gd_fixture(false,false); cbm_store_graph_digest_t out={0};
    bool setup=s && gd_int(cbm_store_get_db(s),"SELECT count(*) FROM nodes",2) &&
        gd_int(cbm_store_get_db(s),"SELECT length(CAST(properties AS BLOB)) FROM nodes WHERE id=-7",4) &&
        gd_int(cbm_store_get_db(s),"SELECT count(*) FROM lsp_surface WHERE typeof(ref_bloom)='blob'",2);
    bool got=setup && gd_p(s,&out); cbm_store_close(s);
    ASSERT_TRUE(setup); ASSERT_TRUE(got); ASSERT_EQ(out.version,1);
    ASSERT_TRUE(out.rows==GD_GOLDEN_ROWS); ASSERT_TRUE(out.framed_bytes==GD_GOLDEN_BYTES);
    ASSERT_TRUE(memcmp(out.sha256,gd_golden_sha,32)==0); PASS();
}

TEST(store_graph_digest_logical_order_and_excluded_storage_are_stable) {
    cbm_store_t *a=gd_fixture(false,false),*b=gd_fixture(true,false);
    cbm_store_graph_digest_t x={0},y={0},z={0},q={0};
    bool setup=a && b;
    bool controls=setup && gd_p(a,&x) && gd_p(b,&y);
    bool layout=controls && gd_sql(cbm_store_get_db(b),
        "CREATE TABLE noise(id INTEGER PRIMARY KEY AUTOINCREMENT,value BLOB);"
        "INSERT INTO noise VALUES(999,zeroblob(70000));DELETE FROM noise;"
        "CREATE INDEX irrelevant_node_name ON nodes(name);PRAGMA reverse_unordered_selects=ON;") == SQLITE_OK;
    bool again=layout && gd_p(b,&z) && gd_read(b,(const unsigned char *)"q",1,&q);
    char dir[1024]={0},path[1200]={0};const char *tmp=th_mktempdir("cbm-digest-layout");
    bool named=tmp && strlen(tmp)<sizeof(dir);if(named)memcpy(dir,tmp,strlen(tmp)+1);
    int n=named?snprintf(path,sizeof(path),"%s/other-name.db",dir):-1;
    sqlite3 *raw=NULL;bool file=n>0 && (size_t)n<sizeof(path) && sqlite3_open(path,&raw)==SQLITE_OK;
    /* VACUUM uses ATTACH internally. Exercise physical layout on the raw
     * fixture, without changing the store connection's ATTACH protection. */
    bool prepared=file && gd_sql(raw,"PRAGMA page_size=8192")==SQLITE_OK &&
        gd_seed(raw,true,false) && gd_sql(raw,"VACUUM")==SQLITE_OK;
    if(raw)sqlite3_close(raw);
    cbm_store_t *disk=prepared?cbm_store_open_path_query(path):NULL;cbm_store_graph_digest_t on_disk={0};
    bool disk_ok=disk && gd_int(cbm_store_get_db(disk),"PRAGMA page_size",8192) && gd_p(disk,&on_disk);
    cbm_store_close(disk);bool cleanup=!dir[0] || th_rmtree(dir)==0;
    cbm_store_close(a);cbm_store_close(b);
    ASSERT_TRUE(named);ASSERT_TRUE(file);ASSERT_TRUE(prepared);ASSERT_TRUE(disk_ok);ASSERT_TRUE(cleanup);
    ASSERT_TRUE(gd_equal(&x,&on_disk));
    ASSERT_TRUE(setup);ASSERT_TRUE(controls);ASSERT_TRUE(gd_equal(&x,&y));
    ASSERT_TRUE(layout);ASSERT_TRUE(again);ASSERT_TRUE(gd_equal(&x,&z));ASSERT_TRUE(gd_different(&x,&q));PASS();
}

TEST(store_graph_digest_every_known_value_and_cross_project_edge_is_bound) {
    /* Every ordinary descriptor column has a valid one-column mutation.
     * Generated columns cannot be assigned; both expression outputs change via properties. */
    static const char *const changes[] = {
        "UPDATE projects SET name='r' WHERE name='q'",
        "UPDATE projects SET indexed_at='later' WHERE name='p'",
        "UPDATE projects SET root_path='/elsewhere' WHERE name='p'",
        "UPDATE file_hashes SET project='q' WHERE rel_path='a'",
        "UPDATE file_hashes SET rel_path='z' WHERE rel_path='a'",
        "UPDATE file_hashes SET sha256='different' WHERE rel_path='a'",
        "UPDATE file_hashes SET mtime_ns=-2 WHERE rel_path='a'",
        "UPDATE file_hashes SET size=2 WHERE rel_path='a'",
        "UPDATE nodes SET id=-8 WHERE id=-7",
        "UPDATE nodes SET project='q' WHERE id=-7",
        "UPDATE nodes SET label='Method' WHERE id=-7",
        "UPDATE nodes SET name='named' WHERE id=-7",
        "UPDATE nodes SET qualified_name='p.changed' WHERE id=-7",
        "UPDATE nodes SET file_path='' WHERE id=-7",
        "UPDATE nodes SET start_line=-1 WHERE id=-7",
        "UPDATE nodes SET end_line=0 WHERE id=-7",
        "UPDATE nodes SET properties=CAST(X'7b7d0079' AS TEXT) WHERE id=-7",
        "UPDATE edges SET id=4 WHERE id=3",
        "UPDATE edges SET project='p' WHERE id=3",
        "UPDATE edges SET source_id=-7 WHERE id=3",
        "UPDATE edges SET target_id=11 WHERE id=3",
        "UPDATE edges SET type='ASYNC_CALLS' WHERE id=3",
        "UPDATE edges SET properties=' ' WHERE id=3",
        "UPDATE project_summaries SET project='q'",
        "UPDATE project_summaries SET summary='new'",
        "UPDATE project_summaries SET source_hash='new'",
        "UPDATE project_summaries SET created_at='new'",
        "UPDATE project_summaries SET updated_at='new'",
        "UPDATE lsp_surface SET project='q' WHERE rel_path='a'",
        "UPDATE lsp_surface SET rel_path='z' WHERE rel_path='a'",
        "UPDATE lsp_surface SET surface_sha='new' WHERE rel_path='a'",
        "UPDATE lsp_surface SET defs_json=' { } ' WHERE rel_path='a'",
        "UPDATE lsp_surface SET ref_bloom=X'' WHERE rel_path='a'",
        "UPDATE lsp_surface SET config_ctx='new' WHERE rel_path='a'",
        "UPDATE index_coverage SET project='q' WHERE rel_path='a'",
        "UPDATE index_coverage SET rel_path='z' WHERE rel_path='a'",
        "UPDATE index_coverage SET kind='new' WHERE rel_path='a'",
        "UPDATE index_coverage SET detail='' WHERE rel_path='a'",
        "UPDATE index_coverage_meta SET project='q'",
        "UPDATE index_coverage_meta SET generation='new'",
        "UPDATE index_coverage_meta SET index_mode='new'",
        "UPDATE index_coverage_meta SET recorded_at='new'",
        "UPDATE index_coverage_meta SET recording_status='new'",
        "UPDATE index_coverage_meta SET ignored_files_stored=2",
        "UPDATE index_coverage_meta SET ignored_files_total=2",
        "UPDATE index_coverage_meta SET coverage_version=2",
        "UPDATE index_coverage_meta SET hash_records_complete=0",
        "UPDATE store_meta SET k='future2' WHERE k='future'",
        "UPDATE store_meta SET v='changed' WHERE k='future'",
        "UPDATE store_meta SET v='fedcba9876543210' WHERE k='db_uid'",
        "UPDATE store_meta SET v='8' WHERE k='mutation_gen'"
    };
    for(size_t i=0;i<sizeof(changes)/sizeof(changes[0]);i++) {
        cbm_store_t *s=gd_fixture(false,true);cbm_store_graph_digest_t before={0},after={0};
        bool setup=s && gd_p(s,&before);
        bool changed=setup && gd_sql(cbm_store_get_db(s),changes[i])==SQLITE_OK &&
            sqlite3_changes(cbm_store_get_db(s))==1;
        bool got=changed && gd_p(s,&after);
        cbm_store_close(s);
        if(!setup || !changed || !got || !gd_different(&before,&after)) {
            fprintf(stderr,"graph digest mutation %zu: %s\n",i,changes[i]);FAIL("known column mutation did not change digest");
        }
    }
    PASS();
}

TEST(store_graph_digest_raw_types_project_bytes_and_schema_sql_are_distinct) {
    static const char *const changes[] = {
        "UPDATE nodes SET properties=CAST(X'7b7d007900' AS TEXT) WHERE id=-7",
        "UPDATE lsp_surface SET ref_bloom=X'00' WHERE rel_path='aa'",
        "UPDATE lsp_surface SET ref_bloom=NULL WHERE rel_path='aa'",
        "UPDATE nodes SET file_path=NULL WHERE id=11",
        "UPDATE nodes SET start_line=0 WHERE id=11",
        "ALTER TABLE projects RENAME TO old_projects;"
        "CREATE TABLE projects(name TEXT COLLATE NOCASE PRIMARY KEY,indexed_at TEXT,root_path TEXT);"
        "INSERT INTO projects SELECT * FROM old_projects;DROP TABLE old_projects;",
        "ALTER TABLE projects RENAME TO old_projects;"
        "CREATE TABLE projects( name TEXT PRIMARY KEY, indexed_at TEXT, root_path TEXT );"
        "INSERT INTO projects SELECT * FROM old_projects;DROP TABLE old_projects;",
        "ALTER TABLE projects RENAME TO old_projects;"
        "CREATE TABLE projects(root_path TEXT,indexed_at TEXT,name TEXT PRIMARY KEY);"
        "INSERT INTO projects(root_path,indexed_at,name) SELECT root_path,indexed_at,name FROM old_projects;DROP TABLE old_projects;",
        "ALTER TABLE edges RENAME TO old_edges;"
        "CREATE TABLE edges(id INTEGER PRIMARY KEY,project TEXT,source_id INTEGER,target_id INTEGER,type TEXT,properties TEXT,"
        "url_path_gen TEXT GENERATED ALWAYS AS (properties || ':v'),local_name_gen TEXT GENERATED ALWAYS AS (properties || ':l'));"
        "INSERT INTO edges(id,project,source_id,target_id,type,properties) SELECT id,project,source_id,target_id,type,properties FROM old_edges;DROP TABLE old_edges;",
        "ALTER TABLE edges RENAME TO old_edges;"
        "CREATE TABLE edges(id INTEGER PRIMARY KEY,project TEXT,source_id INTEGER,target_id INTEGER,type TEXT,properties TEXT,"
        "url_path_gen TEXT GENERATED ALWAYS AS (properties || ':u'),local_name_gen TEXT GENERATED ALWAYS AS (properties || ':m'));"
        "INSERT INTO edges(id,project,source_id,target_id,type,properties) SELECT id,project,source_id,target_id,type,properties FROM old_edges;DROP TABLE old_edges;"
    };
    for(size_t i=0;i<sizeof(changes)/sizeof(changes[0]);i++) {
        cbm_store_t *s=gd_fixture(false,false);cbm_store_graph_digest_t a={0},b={0};
        bool before=s && gd_p(s,&a), mutation=before && gd_sql(cbm_store_get_db(s),changes[i])==SQLITE_OK;
        bool after=mutation && gd_p(s,&b);cbm_store_close(s);
        ASSERT_TRUE(before);ASSERT_TRUE(mutation);ASSERT_TRUE(after);ASSERT_TRUE(gd_different(&a,&b));
    }
    cbm_store_t *s=gd_fixture(false,false);cbm_store_graph_digest_t raw={0},p={0};
    const unsigned char project[]={0xff,':','p'};
    bool added=s && gd_sql(cbm_store_get_db(s),"INSERT INTO projects VALUES(CAST(X'ff3a70' AS TEXT),'t','r')")==SQLITE_OK;
    bool both=added && gd_read(s,project,sizeof(project),&raw) && gd_p(s,&p);
    cbm_store_close(s);ASSERT_TRUE(added);ASSERT_TRUE(both);ASSERT_TRUE(gd_different(&raw,&p));PASS();
}

