TEST(store_graph_digest_schema_and_runtime_types_fail_closed) {
    static const char *const bad[] = {
        "DROP TABLE file_hashes", "DROP TABLE project_summaries", "DROP TABLE lsp_surface",
        "DROP TABLE index_coverage", "DROP TABLE index_coverage_meta", "DROP TABLE edges",
        "DROP TABLE projects",
        "ALTER TABLE file_hashes ADD COLUMN ignored TEXT",
        "ALTER TABLE file_hashes DROP COLUMN size",
        "ALTER TABLE file_hashes RENAME TO old_hashes;CREATE VIEW file_hashes AS SELECT * FROM old_hashes;",
        "DROP TABLE file_hashes;CREATE VIRTUAL TABLE file_hashes USING fts5(project,rel_path,sha256,mtime_ns,size);",
        "ALTER TABLE edges DROP COLUMN local_name_gen;ALTER TABLE edges ADD COLUMN local_name_gen TEXT",
        "ALTER TABLE file_hashes RENAME TO old_hashes;"
        "CREATE TABLE file_hashes(project TEXT,rel_path TEXT,sha256 TEXT,mtime_ns INTEGER,size INTEGER,PRIMARY KEY(rel_path,project));"
        "INSERT INTO file_hashes SELECT * FROM old_hashes;DROP TABLE old_hashes;",
        "CREATE TEMP TABLE file_hashes(project TEXT)",
        "CREATE TEMP VIEW projects AS SELECT 'p' AS name",
        "UPDATE file_hashes SET size=1.5 WHERE rel_path='a'",
        "UPDATE nodes SET name=X'6162' WHERE id=-7",
        "UPDATE lsp_surface SET ref_bloom='bytes' WHERE rel_path='a'",
        "UPDATE nodes SET label=NULL WHERE id=-7",
        "UPDATE projects SET name=NULL WHERE name='q'",
        "UPDATE file_hashes SET rel_path=NULL WHERE rel_path='a'",
        ("ALTER TABLE projects RENAME TO old_projects;CREATE TABLE projects(name TEXT,indexed_at TEXT,root_path TEXT);"
         "INSERT INTO projects SELECT * FROM old_projects;INSERT INTO projects VALUES('p','t','r');DROP TABLE old_projects;")
    };
    for(size_t i=0;i<sizeof(bad)/sizeof(bad[0]);i++) {
        cbm_store_t *s=gd_fixture(false,false);bool setup=s && gd_sql(cbm_store_get_db(s),bad[i])==SQLITE_OK;
        bool rejected=setup && gd_reject(s,CBM_STORE_GRAPH_DIGEST_SCHEMA);cbm_store_close(s);
        if(!setup || !rejected) {fprintf(stderr,"graph schema case %zu: %s\n",i,bad[i]);FAIL("schema/type refusal or fixture failed");}
    }
    /* UTF-16 needs a fresh raw database: an existing UTF-8 schema cannot be recoded by PRAGMA. */
    char dir[1024]={0},path[1200]={0};const char *tmp=th_mktempdir("cbm-digest-utf16");
    bool named=tmp && strlen(tmp)<sizeof(dir);if(named)memcpy(dir,tmp,strlen(tmp)+1);
    int n=named?snprintf(path,sizeof(path),"%s/graph.db",dir):-1;
    sqlite3 *db=NULL;bool file=n>0 && (size_t)n<sizeof(path) && sqlite3_open(path,&db)==SQLITE_OK;
    bool utf16=file && gd_sql(db,"PRAGMA encoding='UTF-16le'")==SQLITE_OK;
    /* The golden rows deliberately CAST raw UTF-8 bytes to TEXT. Those casts
     * have different meanings in a UTF-16 database, so seed ordinary SQL text. */
    for (size_t i=0;utf16 && i<8;i++) utf16=gd_sql(db,gd_schema[i])==SQLITE_OK;
    utf16=utf16 && gd_sql(db,"INSERT INTO projects VALUES('p','t','r')")==SQLITE_OK;
    sqlite3_stmt *encoding=NULL;
    bool checked=utf16 && sqlite3_prepare_v2(db,"PRAGMA encoding",-1,&encoding,NULL)==SQLITE_OK &&
        sqlite3_step(encoding)==SQLITE_ROW && sqlite3_column_type(encoding,0)==SQLITE_TEXT &&
        sqlite3_column_text(encoding,0)!=NULL && sqlite3_column_bytes(encoding,0)==8 &&
        memcmp(sqlite3_column_text(encoding,0),"UTF-16le",8)==0 &&
        sqlite3_step(encoding)==SQLITE_DONE;
    if(encoding && sqlite3_finalize(encoding)!=SQLITE_OK) checked=false;
    utf16=utf16 && checked;
    if(db)sqlite3_close(db);
    cbm_store_t *s=utf16?cbm_store_open_path_query(path):NULL;
    bool rejected=s && gd_reject(s,CBM_STORE_GRAPH_DIGEST_SCHEMA);cbm_store_close(s);
    bool cleanup=!dir[0] || th_rmtree(dir)==0;
    ASSERT_TRUE(named);ASSERT_TRUE(file);ASSERT_TRUE(utf16);ASSERT_TRUE(rejected);ASSERT_TRUE(cleanup);PASS();
}

