        int rc=opened==CBM_STORE_OK?cbm_store_graph_digest(scope,(const unsigned char *)"p",1,&cases[i],&out):-1;
        int latch=scope?cbm_store_read_scope_check(scope):0;
        int rrc=scope?cbm_store_graph_digest(scope,(const unsigned char *)"p",1,&gd_room,&retry):-1;
        int closed=cbm_store_read_scope_close(scope);cbm_store_close(s);
