TEST(store_graph_digest_cancellation_large_blob_never_publishes_prefix) {
    cbm_store_t *control=gd_fixture(false,false);gd_cancel_t c={0};cbm_store_read_scope_t *scope=NULL;
    bool large=control && gd_sql(cbm_store_get_db(control),"UPDATE lsp_surface SET ref_bloom=zeroblob(262145) WHERE rel_path='b'")==SQLITE_OK;
    int opened=large?cbm_store_read_scope_open(control,gd_cancel,&c,&scope):CBM_STORE_ERR;
    cbm_store_graph_digest_t expected={0};c.armed=true;
    int rc=scope?cbm_store_graph_digest(scope,(const unsigned char *)"p",1,&gd_room,&expected):-1;
    uint64_t polls=c.calls;c.armed=false;
    int closed=cbm_store_read_scope_close(scope);cbm_store_close(control);
    ASSERT_TRUE(large);ASSERT_EQ(opened,CBM_STORE_OK);ASSERT_EQ(rc,CBM_STORE_GRAPH_DIGEST_OK);ASSERT_EQ(closed,CBM_STORE_OK);ASSERT_TRUE(polls>1);
    /* Nine bounded, observed positions. Counts do not identify SHA/SQL phases. */
    for(unsigned i=0;i<9;i++) {
        cbm_store_t *s=gd_fixture(false,false);bool setup=s && gd_sql(cbm_store_get_db(s),"UPDATE lsp_surface SET ref_bloom=zeroblob(262145) WHERE rel_path='b'")==SQLITE_OK;
        gd_cancel_t cancel={0};scope=NULL;opened=setup?cbm_store_read_scope_open(s,gd_cancel,&cancel,&scope):CBM_STORE_ERR;
        cbm_store_graph_digest_t out,retry;memset(&out,0xa5,sizeof(out));memset(&retry,0xa5,sizeof(retry));
        cancel.trip=1+(polls-1)*i/8;cancel.armed=true;
        rc=scope?cbm_store_graph_digest(scope,(const unsigned char *)"p",1,&gd_room,&out):-1;
        cancel.armed=false;int latch=scope?cbm_store_read_scope_check(scope):0;
        int again=scope?cbm_store_graph_digest(scope,(const unsigned char *)"p",1,&gd_room,&retry):-1;
        closed=cbm_store_read_scope_close(scope);cbm_store_close(s);
        ASSERT_TRUE(setup);ASSERT_EQ(opened,CBM_STORE_OK);ASSERT_EQ(rc,CBM_STORE_GRAPH_DIGEST_CANCELLED);ASSERT_TRUE(gd_zero(&out));ASSERT_EQ(latch,CBM_STORE_CANCELLED);ASSERT_EQ(again,CBM_STORE_GRAPH_DIGEST_CANCELLED);ASSERT_TRUE(gd_zero(&retry));ASSERT_EQ(closed,CBM_STORE_CANCELLED);
    }
    PASS();
}

typedef struct { const char *denied_table; bool restore; unsigned denials; } gd_auth_t;
static int gd_authorizer(void *opaque,int op,const char *a,const char *b,const char *db,const char *trigger) {
    gd_auth_t *c=opaque;(void)db;(void)trigger;
    if(op==SQLITE_READ && a && c->denied_table &&
       (strcmp(a,c->denied_table)==0 || (strcmp(c->denied_table,"@schema")==0 &&
        (strcmp(a,"sqlite_master")==0 || strcmp(a,"sqlite_schema")==0)))) {
        c->denials++;return SQLITE_DENY;
    }
    if(c->restore && op==SQLITE_PRAGMA && a && b && strcmp(a,"query_only")==0)return SQLITE_DENY;
    return SQLITE_OK;
}
